examples.template:
Box {
    MonarchButton(text = {{trigger}}, onClick = { open = true })
    MonarchPopover(
        expanded = open,
        onDismissRequest = { open = false },
        label = {{label}},
    ) {
        MonarchCheckboxRow(checked = first, onCheckedChange = { first = it }, label = {{options.0.label}})
        MonarchCheckboxRow(checked = second, onCheckedChange = { second = it }, label = {{options.1.label}})
    }
}

examples.setupTemplate:
var open by remember { mutableStateOf(true) }
var first by remember { mutableStateOf({{options.0.checked}}) }
var second by remember { mutableStateOf({{options.1.checked}}) }

examples.setup:
