examples.code:
Box {
    MonarchButton(text = "Filters", onClick = { open = true })
    MonarchPopover(
        expanded = open,
        onDismissRequest = { open = false },
        label = "Filters",
    ) {
        MonarchCheckboxRow(checked = first, onCheckedChange = { first = it }, label = "Only mine")
        MonarchCheckboxRow(checked = second, onCheckedChange = { second = it }, label = "Unassigned")
    }
}

Box {
    MonarchButton(text = "Why this price?", onClick = { open = true }, variant = MonarchButtonVariant.Ghost)
    MonarchPopover(
        expanded = open,
        onDismissRequest = { open = false },
        label = "Why this price",
        side = MonarchPopoverSide.Top,
    ) {
        MonarchText(text = "Seats added this month are charged from the day they were added.")
    }
}
